// TCRN-CROSS-STORY-486 R2 and the mechanism of AC2 (MIN-227 D28; TCRN-CROSS-SUB-348): the helper
// repository's documents are generated by the engine. scripts/render-helper-docs.mjs writes into a
// helper working tree the five helper READMEs, identical to their templates but for the version;
// the skill directory exactly as skill-render writes it; and a package.json that names the helper,
// carries the engine's version and the skill's description A. It lists the files of the working
// tree that the generated tree does not hold and deletes none of them. Every case writes into a
// temporary directory.

import "./helpers/device-home.mjs";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdir, mkdtemp, readdir, readFile, realpath, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import test from "node:test";

import { runCli } from "../dist/build/packages/cli/src/index.js";
import { BRAND } from "../dist/build/packages/core/src/names.js";
import { SKILL_DESCRIPTION } from "../dist/build/packages/core/src/skill-render.js";
import { scanPrivacyEntries } from "../scripts/lib/privacy.mjs";
import { verifyHelperGenerated } from "../scripts/verify-helper-generated.mjs";

const repositoryRoot = resolve(import.meta.dirname, "..");
const script = join(repositoryRoot, "scripts", "render-helper-docs.mjs");
const templateDirectory = join(repositoryRoot, "docs", "readme", BRAND.helper.id);
const descriptionFixture = join(repositoryRoot, "tests", "fixtures", "skill", "description-a.en.txt");
const README_NAMES = ["README.md", "README.en.md", "README.ja.md", "README.ko.md", "README.fr.md"];
const PLACEHOLDER = "{{version}}";
const SKILL = `skill/${BRAND.helper.id}`;
const LOCAL_PATH_REASONS = new Set(["LOCAL_ABSOLUTE_PATH", "LINUX_HOME_PATH", "WINDOWS_USER_PATH"]);

async function scratch(context) {
  const base = await realpath(await mkdtemp(join(tmpdir(), "einzbern-helper-docs-")));
  context.after(() => rm(base, { recursive: true, force: true }));
  return base;
}

function generate(args) {
  const result = spawnSync(process.execPath, [script, ...args], { cwd: repositoryRoot, encoding: "utf8" });
  return { status: result.status, output: JSON.parse(result.stdout.trim()), stderr: result.stderr };
}

async function generated(out, version) {
  const result = generate(["--out", out, "--version", version]);
  assert.equal(result.status, 0, JSON.stringify(result.output));
  assert.equal(result.output.reasonCode, "HELPER_DOCS_RENDERED");
  return result.output;
}

// Every file under root, relative to it with POSIX separators; .git and node_modules are skipped.
async function listFiles(root, prefix = "") {
  const found = [];
  const directory = prefix === "" ? root : join(root, ...prefix.split("/"));
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    if (entry.name === ".git" || entry.name === "node_modules") continue;
    const path = prefix === "" ? entry.name : `${prefix}/${entry.name}`;
    if (entry.isDirectory()) found.push(...await listFiles(root, path));
    else found.push(path);
  }
  return found.sort();
}

async function seed(root, files) {
  for (const [path, text] of Object.entries(files)) {
    const target = join(root, ...path.split("/"));
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, text);
  }
}

test("helper CI reproduces another release version from its pinned generator and refuses drift", async (context) => {
  const out = await scratch(context);
  await generated(out, "7.6.5");
  const result = await verifyHelperGenerated(out);
  assert.equal(result.reasonCode, "HELPER_GENERATED_VERIFIED");
  assert.equal(result.source.renderVersion, "7.6.5");
  assert.match(result.archiveSha256, /^[0-9a-f]{64}$/u);
  const path = join(out, "README.en.md");
  const original = await readFile(path);
  await writeFile(path, "hand edited distribution\n");
  await assert.rejects(verifyHelperGenerated(out), /Generated bytes differ/u);
  await writeFile(path, original);
  const lock = join(out, ".github/engine-source.json");
  const source = JSON.parse(await readFile(lock, "utf8"));
  await writeFile(lock, JSON.stringify({ ...source, commit: "f".repeat(40) }));
  await assert.rejects(verifyHelperGenerated(out), /immutable source reference/u);
});

test("486-R2, AC2: the five helper READMEs are their templates, word for word but for the version", async (context) => {
  const out = await scratch(context);
  const version = "7.6.5";
  await generated(out, version);
  for (const name of README_NAMES) {
    const template = await readFile(join(templateDirectory, name), "utf8");
    assert.ok(template.includes(PLACEHOLDER) && !template.includes(version), `${name} has a version slot`);
    const readme = await readFile(join(out, name), "utf8");
    assert.equal(readme, template.replaceAll(PLACEHOLDER, version), `${name} is its template with ${version} filled in`);
    assert.equal(readme.replaceAll(version, PLACEHOLDER), template, `${name} differs from its template only by the version`);
    assert.equal(readme.includes("{{"), false, `${name} has no unfilled slot`);
    const findings = scanPrivacyEntries([{ label: name, kind: "source", content: readme }], { owner: "render-helper-docs-owner" })
      .filter((finding) => LOCAL_PATH_REASONS.has(finding.split(":")[0]));
    assert.deepEqual(findings, [], `${name} carries no user-home path`);
  }
});

test("486-AC2: the skill directory is skill-render's output for the same version, SKILL.md included", async (context) => {
  const base = await scratch(context);
  const out = join(base, "helper");
  await mkdir(out);
  const version = "7.6.5";
  const report = await generated(out, version);
  const rendered = join(base, "rendered");
  let output = "";
  await runCli(["skill-render", "--out", rendered, "--version", version], { write: (value) => { output += value; } });
  const skill = JSON.parse(output);
  assert.equal(report.skillInstallTreeDigest, skill.installTreeDigest);
  assert.deepEqual(await listFiles(join(out, ...SKILL.split("/"))), [...skill.files, "scripts/create-skill-archive.mjs"].sort());
  for (const path of skill.files) {
    assert.deepEqual(await readFile(join(out, ...SKILL.split("/"), ...path.split("/"))), await readFile(join(rendered, ...path.split("/"))), `${path} is skill-render's`);
  }
  const markdown = await readFile(join(out, ...SKILL.split("/"), "SKILL.md"), "utf8");
  assert.ok(markdown.includes(`${BRAND.engine.name} ${version}:`), "SKILL.md is generated for the version given");
});

test("486-R2: package.json names the helper, carries the engine's version and the skill's description A", async (context) => {
  const out = await scratch(context);
  await generated(out, "7.6.5");
  const text = await readFile(join(out, "package.json"), "utf8");
  const manifest = JSON.parse(text);
  assert.equal(text, `${JSON.stringify(manifest, null, 2)}\n`, "two-space JSON with one final newline");
  assert.equal(manifest.name, BRAND.helper.id);
  assert.equal(manifest.version, "7.6.5");
  const fixture = await readFile(descriptionFixture, "utf8");
  assert.equal(manifest.description, fixture.slice(0, -1), "the finalized English description A");
  assert.equal(manifest.description, SKILL_DESCRIPTION);
  assert.equal(manifest.private, true);

  const defaulted = await scratch(context);
  const engine = JSON.parse(await readFile(join(repositoryRoot, "package.json"), "utf8"));
  const result = generate(["--out", defaulted]);
  assert.equal(result.status, 0, JSON.stringify(result.output));
  assert.equal(result.output.version, engine.version, "the engine's version when --version is not given");
  assert.equal(JSON.parse(await readFile(join(defaulted, "package.json"), "utf8")).version, engine.version);
});

test("486-R2: the files the generated tree does not hold are listed, and none is deleted", async (context) => {
  const out = await scratch(context);
  const stale = {
    "README.md": "# old helper README\n",
    "package.json": "{\n  \"name\": \"old\"\n}\n",
    [`${SKILL}/SKILL.md`]: "old skill\n",
    [`${SKILL}/references/trust-contract.md`]: "retired reference\n",
    [`${SKILL}/scripts/unknown-local-helper.mjs`]: "export {};\n",
    [`${SKILL}/scripts/create-skill-archive.mjs`]: "export {};\n",
    "docs/notes.md": "not generated\n",
  };
  const kept = { "LICENSE": "license text\n", ".gitignore": "node_modules/\n" };
  const skipped = { ".git": "gitdir: elsewhere\n", "node_modules/some/index.js": "export {};\n" };
  await seed(out, { ...stale, ...kept, ...skipped });

  const report = await generated(out, "7.6.5");
  assert.deepEqual(report.extraFiles, ["docs/notes.md", `${SKILL}/references/trust-contract.md`, `${SKILL}/scripts/unknown-local-helper.mjs`]);
  assert.ok(report.files.includes(".github/workflows/ci.yml"), "release generation owns the workflow");
  assert.ok(report.files.includes(`${SKILL}/scripts/create-skill-archive.mjs`), "release generation owns the archiver");
  assert.deepEqual(await readFile(join(out, ...SKILL.split("/"), "scripts/create-skill-archive.mjs")), await readFile(join(repositoryRoot, "scripts/templates/helper/create-skill-archive.mjs")), "the stale archiver is replaced by the release-owned template bytes");
  for (const path of report.extraFiles) {
    assert.equal(await readFile(join(out, ...path.split("/")), "utf8"), stale[path], `${path} is left as it was`);
  }
  for (const [path, text] of Object.entries({ ...kept, ...skipped })) {
    assert.equal(await readFile(join(out, ...path.split("/")), "utf8"), text, `${path} is left as it was`);
  }
  assert.notEqual(await readFile(join(out, "README.md"), "utf8"), stale["README.md"], "a generated file is written over");
  assert.notEqual(await readFile(join(out, ...SKILL.split("/"), "SKILL.md"), "utf8"), stale[`${SKILL}/SKILL.md`]);
  const everything = await listFiles(out);
  assert.deepEqual(everything, [...new Set([...report.files, ...report.extraFiles, ...Object.keys(kept)])].sort(), "the tree is the generated files, the listed ones and the kept ones");
});

test("486-R2: generating twice writes the same bytes and lists nothing on a clean tree", async (context) => {
  const out = await scratch(context);
  const first = await generated(out, "7.6.5");
  assert.deepEqual(first.extraFiles, []);
  const bytes = new Map();
  for (const path of first.files) bytes.set(path, await readFile(join(out, ...path.split("/"))));
  const second = await generated(out, "7.6.5");
  assert.deepEqual(second.files, first.files);
  assert.deepEqual(second.extraFiles, []);
  for (const path of second.files) assert.deepEqual(await readFile(join(out, ...path.split("/"))), bytes.get(path), `${path} is stable`);
  assert.deepEqual(first.files, [
    ...README_NAMES,
    "package.json",
    ".github/workflows/ci.yml",
    ".github/engine-source.json",
    ...first.files.filter((path) => path.startsWith(`${SKILL}/`)),
  ].sort(), "READMEs, package.json, the pinned workflow and the skill directory");
  assert.ok(first.files.includes(`${SKILL}/SKILL.md`) && first.files.includes(`${SKILL}/agents/openai.yaml`));
});

test("486-R2: a refusal writes nothing", async (context) => {
  const base = await scratch(context);
  const out = join(base, "helper");
  await mkdir(out);
  const invalid = generate(["--out", out, "--version", "latest"]);
  assert.equal(invalid.status, 1);
  assert.equal(invalid.output.reasonCode, "HELPER_DOCS_VERSION_INVALID");
  assert.deepEqual(await readdir(out), []);
  assert.equal(generate(["--out", join(base, "absent")]).output.reasonCode, "HELPER_DOCS_OUT_NOT_DIRECTORY");
  assert.equal(generate([]).output.reasonCode, "HELPER_DOCS_OUT_REQUIRED");
  assert.equal(generate(["--out"]).output.reasonCode, "HELPER_DOCS_ARGUMENT_VALUE_MISSING");
  assert.equal(generate(["--out", out, "--out", out]).output.reasonCode, "HELPER_DOCS_ARGUMENT_DUPLICATE");
  assert.equal(generate(["--write", out]).output.reasonCode, "HELPER_DOCS_ARGUMENT_UNKNOWN");
  assert.deepEqual(await readdir(out), []);
});
